class Solution {
public:
    vector<string> getLongestSubsequence(vector<string>& words, vector<int>& groups) {
        vector<string> res;
        res.push_back(words[0]);
        int last = groups[0];
        for (int i = 1; i < (int)words.size(); ++i) {
            if (groups[i] != last) {
                res.push_back(words[i]);
                last = groups[i];
            }
        }
        return res;
    }
};
